def transform_rule(grid):
    h, w = len(grid), len(grid[0])
    result = [[0] * w for _ in range(h)]

    # Find feature cells (non-0, non-5)
    feature_cells = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != 5:
                feature_cells.append((r, c))

    if not feature_cells:
        return [[0] * w for _ in range(h)]

    # Calculate shift
    shift_r = h - max(rc[0] for rc in feature_cells) - 1 - 2
    shift_c = 6 - min(rc[1] for rc in feature_cells) - 2

    # Copy original non-zero cells
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    # Remove markers (5s not orthogonally connected to feature)
    feature_connected_5 = set()
    for r, c in feature_cells:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                feature_connected_5.add((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5 and (r, c) not in feature_connected_5:
                result[r][c] = 0

    # Copy non-5 feature cells with shift
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 5:
                new_r, new_c = r + shift_r, c + shift_c
                if 0 <= new_r < h and 0 <= new_c < w:
                    result[new_r][new_c] = v

    return result

