            if 0<=nr<h and 0<=nc<w and grid[nr][nc] == 5:
                connected_5s.append((nr, nc))

    if not markers:
        return [[0] * w for _ in range(h)]

    markerr, markerc = markers[0]
    shift_r = markerr + 2 - max(r for r,c in feature_cells)
    shiftc = markerc + 1 - max(c for r,c in feature_cells)

    result = [[0] * w for _ in range(h)]

    for r, c in feature_cells:
